// GitHub workflow_run delivery -> every ProjectWorkbench instance that opted in to CI results.
// This node does NOT verify anything: each PW instance verifies GitHub's X-Hub-Signature-256
// itself over the exact raw body, which is why the body is forwarded byte-for-byte (base64).
// Add a line to TARGETS for each PW instance; an instance ignores runs signed for another.
const TARGETS = [
  'http://10.0.0.25/api/ci/github',   // PVI2
];
const item = $input.first();
const h = item.json.headers || {};
let raw;
try { raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('base64'); }
catch (e) { throw new Error('Raw body missing: the Webhook node needs the "Raw Body" option on'); }
const envelope = {
  raw,
  signature: h['x-hub-signature-256'] || '',
  event: h['x-github-event'] || '',
  delivery: h['x-github-delivery'] || '',
};
// Only completed workflow runs are of interest; everything else stops here (PW would ignore it anyway).
if (envelope.event !== 'workflow_run') return [];
return TARGETS.map((url) => ({ json: { url, body: envelope } }));
